const input=$json.body??$json;
const text=v=>v===null||v===undefined?'':String(v).trim();
const bool=v=>typeof v==='boolean'?v:['true','1','yes','on'].includes(text(v).toLowerCase());

const clinic_name=text(input.clinic_name);
const mobile=text(input.mobile);
const channel=text(input.channel||'whatsapp').toLowerCase();
const offer_id=Number(input.offer_id);
const offer_token=text(input.offer_token);
const waitlist_id=Number(input.waitlist_id??0);
const doctor_name=text(input.doctor_name);
const service_name=text(input.service_name);
const offered_date=text(input.offered_date);
const offered_start_time=text(input.offered_start_time);
const offered_end_time=text(input.offered_end_time);
const offer_expires_at=text(input.offer_expires_at);
const webhook_base_url=text(input.webhook_base_url||'http://localhost:5678/webhook').replace(/\/+$/,'');
const confirm_queue=bool(input.confirm_queue);
const errors=[];

if(!clinic_name)errors.push({field:'clinic_name',message:'نام کلینیک الزامی است.'});
if(!/^\+?[0-9]{8,15}$/.test(mobile))errors.push({field:'mobile',message:'شماره موبایل معتبر نیست.'});
if(!['whatsapp','sms','email','phone','web_push','in_app'].includes(channel))errors.push({field:'channel',message:'کانال معتبر نیست.'});
if(!Number.isInteger(offer_id)||offer_id<1)errors.push({field:'offer_id',message:'شناسه پیشنهاد معتبر نیست.'});
if(!offer_token)errors.push({field:'offer_token',message:'توکن پیشنهاد الزامی است.'});
if(!Number.isInteger(waitlist_id)||waitlist_id<0)errors.push({field:'waitlist_id',message:'شناسه لیست انتظار معتبر نیست.'});
if(!doctor_name)errors.push({field:'doctor_name',message:'نام پزشک الزامی است.'});
if(!service_name)errors.push({field:'service_name',message:'نام خدمت الزامی است.'});
if(!/^\d{4}-\d{2}-\d{2}$/.test(offered_date))errors.push({field:'offered_date',message:'تاریخ پیشنهاد باید YYYY-MM-DD باشد.'});
if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(offered_start_time))errors.push({field:'offered_start_time',message:'ساعت شروع معتبر نیست.'});
if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(offered_end_time))errors.push({field:'offered_end_time',message:'ساعت پایان معتبر نیست.'});
if(offer_expires_at&&Number.isNaN(Date.parse(offer_expires_at)))errors.push({field:'offer_expires_at',message:'زمان انقضا معتبر نیست.'});
if(!/^https?:\/\/.+/i.test(webhook_base_url))errors.push({field:'webhook_base_url',message:'آدرس Webhook معتبر نیست.'});
if(confirm_queue!==true)errors.push({field:'confirm_queue',message:'ثبت پیام باید تأیید شود.'});

return [{json:{
 clinic_name,mobile,channel,offer_id,offer_token,waitlist_id,doctor_name,
 service_name,offered_date,offered_start_time,offered_end_time,offer_expires_at,
 webhook_base_url,queue_url:`${webhook_base_url}/clinic/communications/messages/queue`,
 confirm_queue,validation_status:errors.length?'invalid':'valid',errors
}}];
